# Telegram бот для записи клиентов

import asyncio
from datetime import datetime, timedelta
from aiogram import F
from aiogram.filters import Command
from aiogram.types import Message, CallbackQuery, InlineKeyboardMarkup, InlineKeyboardButton
from aiogram.fsm.context import FSMContext
from aiogram.fsm.state import State, StatesGroup
import aiohttp
import os
from dotenv import load_dotenv

from app.scheduler.reminder import send_remind_for_business, send_remind_for_client
from bot.init_bot import create_bot, dp


load_dotenv()

# Конфигурация с проверками
API_URL = os.getenv("API_URL", "http://localhost:8000/api/v1")
API_KEY = os.getenv("API_KEY", "test-api-key-12345")

if not API_KEY:
    raise ValueError("API_KEY не задан в переменных окружения")

TELEGRAM_BOT_TOKEN = os.getenv("TELEGRAM_BOT_TOKEN")
if not TELEGRAM_BOT_TOKEN:
    raise ValueError("TELEGRAM_BOT_TOKEN не задан в переменных окружения")


class BookingStates(StatesGroup):
    choosing_service = State()
    choosing_staff = State()
    choosing_date = State()
    choosing_time = State()


async def api_request(method: str, endpoint: str, data: dict = None, params: dict = None):
    """Выполняет запрос к API"""
    headers = {"X-API-Key": API_KEY}
    url = f"{API_URL}{endpoint}"
    
    async with aiohttp.ClientSession() as session:
        try:
            if method == "GET":
                async with session.get(url, headers=headers, params=params or data) as response:
                    if response.status != 200:
                        raise Exception(f"API error: {response.status}")
                    return await response.json()
            elif method == "POST":
                async with session.post(url, headers=headers, json=data, params=params) as response:
                    if response.status != 200:
                        raise Exception(f"API error: {response.status}")
                    return await response.json()
            elif method == "DELETE":
                async with session.delete(url, headers=headers) as response:
                    if response.status != 200:
                        raise Exception(f"API error: {response.status}")
                    return await response.json()
        except aiohttp.ClientError as e:
            raise Exception(f"Connection error: {str(e)}")


@dp.message(Command("start"))
async def cmd_start(message: Message):
    """Обработчик команды /start"""
    await message.answer(
        f"Привет, {message.from_user.first_name}!\n\n"
        "Я бот для записи на услуги.\n\n"
        "Команды:\n"
        "/book - Записаться на услугу\n"
        "/my_appointments - Мои записи"
    )


@dp.message(Command("book"))
async def cmd_book(message: Message, state: FSMContext):
    """Начало процесса записи"""
    # Получаем или создаем клиента
    client_data = await api_request(
        "POST",
        "/clients/get-or-create/",
        params={"tg_id": message.from_user.id, "client_name": message.from_user.first_name}
    )
    
    await state.update_data(client_id=client_data["id"])
    
    # Получаем список услуг
    services = await api_request("GET", "/services/")
    
    if not services:
        await message.answer("К сожалению, услуги пока недоступны.")
        return
    
    # Создаем клавиатуру с услугами
    buttons = []
    for service in services:
        buttons.append([InlineKeyboardButton(
            text=f"{service['name']} - {service['price']}₽ ({service['duration_minutes']}мин)",
            callback_data=f"service_{service['id']}"
        )])
    
    # Добавляем кнопку отмены
    buttons.append([InlineKeyboardButton(text="❌ Отменить", callback_data="cancel")])
    
    keyboard = InlineKeyboardMarkup(inline_keyboard=buttons)
    await message.answer("Выберите услугу:", reply_markup=keyboard)
    await state.set_state(BookingStates.choosing_service)


@dp.callback_query(F.data.startswith("service_"))
async def process_service_selection(callback: CallbackQuery, state: FSMContext):
    """Обработка выбора услуги"""
    service_id = int(callback.data.split("_")[1])
    
    # Получаем услугу, чтобы сохранить длительность
    services = await api_request("GET", "/services/")
    service = next((s for s in services if s["id"] == service_id), None)
    if not service:
        await callback.message.answer("Услуга не найдена.")
        return
    
    duration_minutes = service["duration_minutes"]
    await state.update_data(service_id=service_id, duration_minutes=duration_minutes)
    
    # Получаем список сотрудников
    staffs = await api_request("GET", "/staffs/")
    
    if not staffs:
        await callback.message.answer("К сожалению, сотрудники пока недоступны.")
        await state.clear()
        return
    
    # Создаем клавиатуру с сотрудниками
    buttons = []
    for staff in staffs:
        buttons.append([InlineKeyboardButton(
            text=f"{staff['name']} - {staff['role']}",
            callback_data=f"staff_{staff['id']}"
        )])
    
    # Добавляем кнопку отмены
    buttons.append([InlineKeyboardButton(text="❌ Отменить", callback_data="cancel")])
    
    keyboard = InlineKeyboardMarkup(inline_keyboard=buttons)
    await callback.message.edit_text("Выберите мастера:", reply_markup=keyboard)
    await state.set_state(BookingStates.choosing_staff)


@dp.callback_query(F.data.startswith("staff_"))
async def process_staff_selection(callback: CallbackQuery, state: FSMContext):
    """Обработка выбора сотрудника - показываем дни со свободными слотами"""
    staff_id = int(callback.data.split("_")[1])
    await state.update_data(staff_id=staff_id)
    
    # Получаем service_id из состояния
    data = await state.get_data()
    service_id = data.get("service_id")
    if not service_id:
        await callback.message.answer("Ошибка: не выбрана услуга.")
        await state.clear()
        return
    
    try:
        # Получаем дни со свободными слотами, передавая service_id
        free_days = await api_request(
            "GET",
            f"/staffs/{staff_id}/free-days/",
            params={"service_id": service_id}
        )
    except Exception as e:
        await callback.message.answer(f"Ошибка при получении дней: {str(e)}")
        await state.clear()
        return
    
    # Проверяем на ошибку
    if isinstance(free_days, dict) and "detail" in free_days:
        await callback.message.answer(f"Ошибка: {free_days['detail']}")
        await state.clear()
        return
    
    # API может вернуть словарь вместо списка
    if isinstance(free_days, dict):
        free_days = free_days.get("days", []) or list(free_days.values())
    
    if not free_days or not isinstance(free_days, list):
        await callback.message.edit_text("К сожалению, на ближайший месяц нет свободных слотов.")
        await state.clear()
        return
    
    # Создаем клавиатуру с днями (максимум 14 кнопок)
    keyboard_buttons = []
    row = []
    for day in free_days[:14]:
        if isinstance(day, dict):
            date_str = day.get("date")
            slots_count = day.get("slots_count", day.get("slots", "?"))
        else:
            date_str = str(day)
            slots_count = "?"
        
        if not date_str:
            continue
        
        try:
            date_obj = datetime.strptime(date_str, "%Y-%m-%d")
        except (ValueError, TypeError):
            continue
        
        day_name = date_obj.strftime("%A")
        day_names_ru = {
            "Monday": "Пн", "Tuesday": "Вт", "Wednesday": "Ср",
            "Thursday": "Чт", "Friday": "Пт", "Saturday": "Сб", "Sunday": "Вс"
        }
        day_name_short = day_names_ru.get(day_name, day_name)
        
        text = f"{date_obj.strftime('%d.%m')} {day_name_short} ({slots_count} сл.)"
        row.append(InlineKeyboardButton(text=text, callback_data=f"date_{date_str}"))
        
        if len(row) == 2:
            keyboard_buttons.append(row)
            row = []
    
    if row:
        keyboard_buttons.append(row)
    
    if not keyboard_buttons:
        await callback.message.edit_text("К сожалению, на ближайший месяц нет свободных слотов.")
        await state.clear()
        return
    
    keyboard = InlineKeyboardMarkup(inline_keyboard=keyboard_buttons)
    await callback.message.edit_text("Выберите дату (показаны дни со свободными слотами):", reply_markup=keyboard)
    await state.set_state(BookingStates.choosing_date)


@dp.callback_query(F.data.startswith("date_"))
async def process_date_selection(callback: CallbackQuery, state: FSMContext):
    """Обработка выбора даты"""
    date_str = callback.data.split("_")[1]
    await state.update_data(date=date_str)
    
    data = await state.get_data()
    staff_id = data["staff_id"]
    service_id = data.get("service_id")
    if not service_id:
        await callback.message.edit_text("Ошибка: не выбрана услуга.")
        await state.clear()
        return
    
    # Получаем свободные слоты с service_id
    try:
        free_slots = await api_request(
            "GET",
            f"/staffs/{staff_id}/free-slots/",
            params={"date": date_str, "service_id": service_id}
        )
    except Exception as e:
        await callback.message.edit_text(f"Ошибка при получении слотов: {str(e)}")
        await state.clear()
        return
    
    if not free_slots:
        await callback.message.edit_text("К сожалению, на эту дату нет свободных слотов.")
        await state.clear()
        return
    
    # Создаем клавиатуру со временем
    buttons = []
    for slot in free_slots:
        # slot приходит в ISO формате с UTC, например "2025-05-30T09:00:00+00:00"
        dt = datetime.fromisoformat(slot)
        buttons.append([InlineKeyboardButton(
            text=dt.strftime('%H:%M'),
            callback_data=f"time_{slot}"
        )])
    
    # Добавляем кнопку отмены
    buttons.append([InlineKeyboardButton(text="❌ Отменить", callback_data="cancel")])
    
    keyboard = InlineKeyboardMarkup(inline_keyboard=buttons)
    await callback.message.edit_text("Выберите время:", reply_markup=keyboard)
    await state.set_state(BookingStates.choosing_time)


@dp.callback_query(F.data.startswith("time_"))
async def process_time_selection(callback: CallbackQuery, state: FSMContext):
    """Обработка выбора времени и создание записи"""
    start_time_str = callback.data.split("time_")[1]
    data = await state.get_data()
    
    # Получаем длительность услуги
    duration_minutes = data.get("duration_minutes", 60)
    
    start_time = datetime.fromisoformat(start_time_str)
    end_time = start_time + timedelta(minutes=duration_minutes)
    
    # Создаем запись
    appointment_data = {
        "client_id": data["client_id"],
        "staff_id": data["staff_id"],
        "service_id": data["service_id"],
        "start_time": start_time.isoformat(),
        "end_time": end_time.isoformat()
    }
    
    try:
        result = await api_request("POST", "/appointments/", appointment_data)
        
        # Создаем кнопку отмены записи
        keyboard = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="❌ Отменить запись", callback_data=f"cancel_{result['id']}")]
        ])
        
        await callback.message.edit_text(
            f"✅ Запись успешно создана!\n\n"
            f"Дата: {start_time.strftime('%d.%m.%Y')}\n"
            f"Время: {start_time.strftime('%H:%M')} - {end_time.strftime('%H:%M')}\n"
            f"ID записи: {result['id']}",
            reply_markup=keyboard
        )
    except Exception as e:
        await callback.message.edit_text(f"❌ Ошибка при создании записи: {str(e)}")
    
    await state.clear()


@dp.message(Command("my_appointments"))
async def cmd_my_appointments(message: Message):
    """Показать записи клиента"""
    # Получаем или создаем клиента
    client_data = await api_request(
        "POST",
        "/clients/get-or-create/",
        params={"tg_id": message.from_user.id, "client_name": message.from_user.first_name}
    )
    
    # Получаем записи клиента
    appointments = await api_request("GET", f"/clients/{client_data['id']}/appointments/")
    
